def tg_call(method,payload):
 data=json.dumps(payload,ensure_ascii=False).encode();req=Request(f"https://api.telegram.org/bot{BOT_TOKEN}/{method}",data=data,headers={"Content-Type":"application/json"},method="POST")
 try:
  with urlopen(req,timeout=15) as r:return json.loads(r.read().decode())
 except Exception:return {"ok":False}
async def tg(method,payload):return await asyncio.to_thread(tg_call,method,payload)
async def subscribed(uid):
 ch=await get_setting('channel','')
 if not ch:return True
 r=await tg('getChatMember',{'chat_id':ch,'user_id':uid});x=r.get('result',{});return r.get('ok',False) and (x.get('status') in ('creator','administrator','member') or (x.get('status')=='restricted' and x.get('is_member',False)))

def sign_obj(obj):
 raw=json.dumps(obj,ensure_ascii=False,separators=(',',':')).encode();sig=hmac.new(SECRET_KEY,raw,hashlib.sha256).hexdigest();b=base64.urlsafe_b64encode(raw).decode().rstrip('=');return b+'.'+sig
def unsign(token):
 try:
  b,s=token.rsplit('.',1);raw=base64.urlsafe_b64decode(b+'='*((4-len(b)%4)%4));good=hmac.new(SECRET_KEY,raw,hashlib.sha256).hexdigest()
  if not hmac.compare_digest(s,good):return None
  o=json.loads(raw);return o if o.get('exp',0)>=int(time.time()) else None
 except:return None

