async def handle_update(u):
 if 'message' in u:
  m=u['message'];fr=m.get('from',{});await save_user(fr)
  if m.get('chat',{}).get('type')!='private':return
  text=m.get('text','')
  if text.startswith('/start'):
   arg=text.split(maxsplit=1)[1] if len(text.split())>1 else ''
   ch=arg[3:] if arg.startswith('ch_') else None
   if ch:
    p=await db()
    async with p.acquire() as c: exists=await c.fetchval('SELECT 1 FROM challenges WHERE token=$1 AND used=false',ch)
    if exists:return await send_welcome(fr['id'],fr.get('first_name',''),ch)
   return await send_welcome(fr['id'],fr.get('first_name',''))
  if text=='/admin' and fr['id'] in ADMIN_IDS:return await send_admin(fr['id'])
  if text=='/cancel' and fr['id'] in ADMIN_IDS:admin_state.pop(fr['id'],None);return await tg('sendMessage',{'chat_id':fr['id'],'text':'❌ Bekor qilindi.'})
  if text=='/yes' and fr['id'] in ADMIN_IDS and admin_state.get(fr['id'],{}).get('mode')=='broadcast_confirm':return await do_broadcast(fr['id'])
  if fr['id'] in ADMIN_IDS and fr['id'] in admin_state:return await admin_flow(m)
 elif 'callback_query' in u:
  c=u['callback_query'];fr=c.get('from',{});await save_user(fr);data=c.get('data','');await tg('answerCallbackQuery',{'callback_query_id':c['id']})
  if data.startswith('subcheck'):
   ch=data.split(':',1)[1] if ':' in data else None
   if not await subscribed(fr['id']):return await tg('sendMessage',{'chat_id':fr['id'],'text':'❌ Hali kanalga obuna bo‘lmagansiz.'})
   return await tg('sendMessage',{'chat_id':fr['id'],'text':'✅ Obuna tasdiqlandi.', 'reply_markup':open_keyboard(ch)})
  if data.startswith('ad:') and fr['id'] in ADMIN_IDS:return await admin_callback(fr['id'],data[3:])

async def send_admin(uid):
 kb={'inline_keyboard':[[{'text':'📊 Statistika','callback_data':'ad:stats'}],[{'text':'📢 Kanal qo‘shish / almashtirish','callback_data':'ad:addch'}],[{'text':'🗑 Kanalni o‘chirish','callback_data':'ad:delch'}],[{'text':'👤 Userga xabar','callback_data':'ad:user'}],[{'text':'📣 Hammaga xabar','callback_data':'ad:all'}],[{'text':'🏆 Top reyting','callback_data':'ad:top'}]]}
 await tg('sendMessage',{'chat_id':uid,'text':'⚙️ <b>ZAKO ADMIN</b>\n\nKerakli bo‘limni tanlang.', 'parse_mode':'HTML','reply_markup':kb})
async def admin_callback(a,mode):
 p=await db()
 if mode=='stats':
  async with p.acquire() as c:
   vals=[await c.fetchval(q) for q in ["SELECT count(*) FROM users","SELECT count(*) FROM users WHERE joined_at>=now()-interval '1 day'","SELECT count(*) FROM users WHERE joined_at>=now()-interval '7 days'","SELECT count(*) FROM users WHERE last_seen>=now()-interval '1 day'","SELECT count(*) FROM scores"]]
  return await tg('sendMessage',{'chat_id':a,'text':f'📊 <b>Statistika</b>\n\n👤 Jami: <b>{vals[0]}</b>\n🆕 24 soat: <b>{vals[1]}</b>\n📅 7 kun: <b>{vals[2]}</b>\n🟢 Faol 24 soat: <b>{vals[3]}</b>\n🧠 Ishlangan testlar: <b>{vals[4]}</b>','parse_mode':'HTML'})
 if mode=='addch':admin_state[a]={'mode':'channel'};return await tg('sendMessage',{'chat_id':a,'text':'📢 Kanal username yoki ID yuboring. Masalan @zako_kanal yoki -100123...'})
 if mode=='delch':await set_setting('channel','');await set_setting('channel_url','');return await tg('sendMessage',{'chat_id':a,'text':'🗑 Majburiy obuna o‘chirildi.'})
 if mode=='user':admin_state[a]={'mode':'user_id'};return await tg('sendMessage',{'chat_id':a,'text':'👤 User Telegram ID yuboring.'})
 if mode=='all':admin_state[a]={'mode':'broadcast_prepare'};return await tg('sendMessage',{'chat_id':a,'text':'📣 Hammaga yuboriladigan xabarni yuboring. Men tasdiqlashni so‘rayman.'})
 if mode=='top':
  async with p.acquire() as c:rows=await c.fetch("SELECT u.first_name,u.username,COALESCE(sum(s.pct),0)::int score FROM users u LEFT JOIN scores s ON s.telegram_id=u.telegram_id GROUP BY u.telegram_id ORDER BY score DESC,u.telegram_id LIMIT 10")
  text='🏆 <b>TOP 10</b>\n\n'+''.join(f"{i}. {htmlmod.escape(r['first_name'] or r['username'] or 'ZAKO')} — <b>{r['score']}</b>\n" for i,r in enumerate(rows,1));return await tg('sendMessage',{'chat_id':a,'text':text,'parse_mode':'HTML'})
async def admin_flow(m):
 a=m['from']['id'];st=admin_state.pop(a);mode=st.get('mode')
 if mode=='channel':
  admin_state[a]={'mode':'channel_url','channel':(m.get('text') or '').strip()};return await tg('sendMessage',{'chat_id':a,'text':'🔗 Endi kanalning to‘liq linkini yuboring: https://t.me/...'})
 if mode=='channel_url':
  ch=st['channel'];url=(m.get('text') or '').strip();await set_setting('channel',ch);await set_setting('channel_url',url);return await tg('sendMessage',{'chat_id':a,'text':'✅ Majburiy obuna kanali saqlandi.'})
 if mode=='user_id':
  try:uid=int((m.get('text') or '').strip())
  except:return await tg('sendMessage',{'chat_id':a,'text':'❌ Raqamli Telegram ID yuboring.'})
  admin_state[a]={'mode':'send_user','uid':uid};return await tg('sendMessage',{'chat_id':a,'text':'✍️ Endi yuboriladigan xabarni yuboring.'})
 if mode=='send_user':
  try:await tg('copyMessage',{'chat_id':st['uid'],'from_chat_id':a,'message_id':m['message_id']});return await tg('sendMessage',{'chat_id':a,'text':'✅ Xabar yuborildi.'})
  except:return await tg('sendMessage',{'chat_id':a,'text':'❌ Xabar yuborilmadi.'})
 if mode=='broadcast_prepare':
  admin_state[a]={'mode':'broadcast_confirm','message_id':m['message_id']};return await tg('sendMessage',{'chat_id':a,'text':'⚠️ Shu xabarni HAMMA foydalanuvchiga yuboraymi?\n\n/yes — yuborish\n/cancel — bekor qilish'})
async def do_broadcast(a):
 st=admin_state.pop(a,None)
 if not st or st.get('mode')!='broadcast_confirm':return await tg('sendMessage',{'chat_id':a,'text':'❌ Broadcast topilmadi. Qaytadan boshlang.'})
 p=await db()
 async with p.acquire() as c:rows=await c.fetch('SELECT telegram_id FROM users')
 ok=bad=0
 for r in rows:
  z=await tg('copyMessage',{'chat_id':r['telegram_id'],'from_chat_id':a,'message_id':st['message_id']})
  if z.get('ok'):ok+=1
  else:bad+=1
  await asyncio.sleep(.05)
 await tg('sendMessage',{'chat_id':a,'text':f'📣 Yakunlandi.\n✅ Yetdi: {ok}\n❌ Yetmadi: {bad}'})

